body=world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(0,3,12));collider=world.createCollider(RAPIER.ColliderDesc.capsule(.55,.35),body);controller=world.createCharacterController(.035);
