const child=await loadModel('./assets/shalev-alone.glb',1.2);setupAvatar(child,1.2);isSpace?addSpaceSuit(child,{accent:0x75d7b5}):addSwimGear(child,0xffc869);scene.add(child);companion=new Companion(world,child);
