const castle=await loadModel('./assets/castle.glb',8),miniScene=new THREE.Scene();miniScene.background=new THREE.Color(0xb6dace);miniScene.add(castle,new THREE.HemisphereLight(0xfff3dd,0x5c796a,3));miniCam=new THREE.PerspectiveCamera(50,1.75,.1,80);miniCam.position.set(11,8,12);miniCam.lookAt(0,3,0);mini=new THREE.WebGLRenderer({canvas:$('#castleView'),antialias:false});mini.setSize(140,80,false);
function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}resize();window.addEventListener('resize',resize);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();state.paused=true;fail('התצוגה נעצרה. טען שוב כדי להמשיך.')});ready=true;$('#loading').hidden=true;message(isSpace?'שליו: החליפות מוכנות! נרחף בין האסטרואידים אל הלוויין הזהוב.':'שליו: אני שוחה בעקבותיך! החזק ↑ או ↓ לשינוי הגובה.');updateGoal();clock.start();
